'use strict';

// MODULES //

import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import strided from './../../../../../../base/fftpack/generic/sinqi';
import ndarraylike2scalar from '@stdlib/ndarray/base/ndarraylike2scalar';


// MAIN //

/**
* Initializes a workspace array for performing a quarter-wave sine transform on a one-dimensional ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the length of the sequence to transform.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarrayLike} input ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import Slice from '@stdlib/slice/ctor';
* import slice from '@stdlib/ndarray/slice';
*
* var N = 8;
* var len = scalar2ndarray( N, {
*     'dtype': 'int32'
* });
*
* var w = new Float64Vector( ( 3*N ) + 34 );
*
* var out = sinqi( [ w, len ] );
* // returns <ndarray>
*
* var bool = ( out === w );
* // returns true
*
* var cosineTable = slice( w, new Slice( 0, N ) );
* // returns <ndarray>[ ~0.98, ~0.92, ~0.83, ~0.7, ~0.56, ~0.38, ~0.2, ~0.0 ]
*
* var twiddleFactors = slice( w, new Slice( 2*N, 3*N ) );
* // returns <ndarray>[ ~0.707, ~0.707, 0, 0, 0, 0, 0, 0 ]
*
* var factors = slice( w, new Slice( 3*N, ( 3*N ) + 4 ) );
* // returns <ndarray>[ 8, 2, 2, 4 ]
*/
function sinqi( arrays ) {
	var w;
	var N;

	w = arrays[ 0 ];
	N = ndarraylike2scalar( arrays[ 1 ] );
	strided( N, getData( w ), getStride( w, 0 ), getOffset( w ) );
	return w;
}


// EXPORTS //

export default sinqi;
