'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray/base/numel-dimension';
import getStride from '@stdlib/ndarray/base/stride';
import getOffset from '@stdlib/ndarray/base/offset';
import getData from '@stdlib/ndarray/base/data-buffer';
import strided from './../../../../../../base/fftpack/generic/rfftf';


// MAIN //

/**
* Computes the forward discrete Fourier transform (DFT) of a real-valued one-dimensional ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional workspace ndarray containing pre-computed values.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarrayLike} input ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray/vector/float64';
* import scalar2ndarray from '@stdlib/ndarray/from-scalar';
* import rffti from '@stdlib/fft/base/fftpack/ndarray/generic/rffti';
*
* var N = 4;
* var len = scalar2ndarray( N, {
*     'dtype': 'int32'
* });
*
* var w = new Float64Vector( ( 2*N ) + 34 );
* rffti( [ w, len ] );
*
* var r = new Float64Vector( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* var out = rfftf( [ r, w ] );
* // returns <ndarray>[ 10.0, -2.0, 2.0, -2.0 ]
*
* var bool = ( out === r );
* // returns true
*/
function rfftf( arrays ) {
	var r;
	var w;

	r = arrays[ 0 ];
	w = arrays[ 1 ];
	strided( numelDimension( r, 0 ), getData( r ), getStride( r, 0 ), getOffset( r ), getData( w ), getStride( w, 0 ), getOffset( w ) ); // eslint-disable-line max-len
	return r;
}


// EXPORTS //

export default rfftf;
